import os
from typing import Any, Dict, Optional
from urllib.parse import urlencode

import requests


AUTH0_DOMAIN = os.environ["AUTH0_DOMAIN"]  # e.g. "your-tenant.us.auth0.com"
AUTH0_CLIENT_ID = os.environ["AUTH0_CLIENT_ID"]
AUTH0_CLIENT_SECRET = os.environ["AUTH0_CLIENT_SECRET"]
AUTH0_REDIRECT_URI = os.environ["AUTH0_REDIRECT_URI"]


class FederatedLoginError(Exception):
    pass


def build_authorize_url(
    state: str,
    scope: str = "openid profile email",
    audience: Optional[str] = None,
    connection: Optional[str] = None,
) -> str:
    params = {
        "response_type": "code",
        "client_id": AUTH0_CLIENT_ID,
        "redirect_uri": AUTH0_REDIRECT_URI,
        "scope": scope,
        "state": state,
    }
    if audience:
        params["audience"] = audience
    if connection:
        params["connection"] = connection
    return f"https://{AUTH0_DOMAIN}/authorize?{urlencode(params)}"


def handle_callback(
    query_params: Dict[str, Any],
    expected_state: Optional[str] = None,
    timeout: int = 15,
) -> Dict[str, Any]:
    if "error" in query_params:
        description = query_params.get("error_description") or query_params["error"]
        raise FederatedLoginError(f"Authorization failed: {description}")

    code = query_params.get("code")
    state = query_params.get("state")

    if not code:
        raise FederatedLoginError("Missing authorization code")
    if expected_state is not None and state != expected_state:
        raise FederatedLoginError("Invalid state")

    token_url = f"https://{AUTH0_DOMAIN}/oauth/token"
    payload = {
        "grant_type": "authorization_code",
        "client_id": AUTH0_CLIENT_ID,
        "client_secret": AUTH0_CLIENT_SECRET,
        "code": code,
        "redirect_uri": AUTH0_REDIRECT_URI,
    }
    headers = {"Content-Type": "application/json"}

    response = requests.post(token_url, json=payload, headers=headers, timeout=timeout)

    try:
        data = response.json()
    except ValueError as exc:
        raise FederatedLoginError("Token endpoint returned non-JSON response") from exc

    if response.status_code != 200:
        message = data.get("error_description") or data.get("error") or "Token exchange failed"
        raise FederatedLoginError(message)

    normalized = {
        "access_token": data.get("access_token"),
        "id_token": data.get("id_token"),
        "refresh_token": data.get("refresh_token"),
        "token_type": data.get("token_type"),
        "expires_in": data.get("expires_in"),
        "scope": data.get("scope"),
    }

    if not normalized["access_token"] and not normalized["id_token"]:
        raise FederatedLoginError("No usable tokens returned by Auth0")

    return normalized
